pub fn get_svg(name: &str) -> Option<&'static str> {
    let clean_name = name.trim_start_matches("kenney/").trim_start_matches("kenney-");
    for (k, v) in KENNEY_SVGS {
        if *k == clean_name {
            return Some(*v);
        }
    }
    None
}
